select account_type, case when status in ('FROZEN', 'OPEN') then 'priority' else 'other' end as status_group, date_format(opened_date, 'yyyy-MM') as opened_month, count(case when status = 'CLOSED' then 1 end) as closed_count, round(avg(balance), 2) as avg_balance, count(balance) as balance_count from accounts where account_type in ('CHECKING', 'SAVINGS') or balance <= 62000 group by 1, 2, 3 order by 2 desc;
